use smaul_native::dataset::{DatasetStream,TokenBatch};
use smaul_native::dataset_multi::MultiFileDatasetStream;
use smaul_native::model_io::PretrainedModel;
use smaul_native::model_gradients::ModelGradients;
use smaul_native::model_train_step::ModelTrainStep;
use smaul_native::sft_dataset::SftDataset;
use smaul_native::training::{OptimizerKind,TrainStep};
use ndarray::{Array1,Array2};
use serde::{Deserialize,Serialize};
use std::env;
use std::fs;
use std::path::{Path,PathBuf};

#[derive(Default)]struct Args{model_dir:PathBuf,dataset:PathBuf,output_dir:PathBuf,mode:String,steps:usize,ctx_len:usize,batch_size:usize,grad_accum:usize,lr:f32,min_lr:f32,warmup:usize,save_every:usize,log_every:usize,resume:bool,optimizer:String}
#[derive(Serialize,Deserialize,Default)]struct State{step:usize,tokens:usize}
enum Data{Single(DatasetStream),Multi(MultiFileDatasetStream),Sft(SftDataset)}
impl Data{fn next(&mut self)->Result<Option<TokenBatch>,String>{match self{Self::Single(x)=>x.next_batch(),Self::Multi(x)=>x.next_batch(),Self::Sft(_)=>Ok(None)}}}
fn value(args:&[String],name:&str,default:&str)->String{args.windows(2).find(|x|x[0]==name).map(|x|x[1].clone()).unwrap_or_else(||default.into())}
fn has(args:&[String],name:&str)->bool{args.iter().any(|x|x==name)}
fn parse()->Args{let a:Vec<String>=env::args().collect();let dataset=value(&a,"--dataset",&value(&a,"--dataset-dir","./datasets/train.jsonl"));Args{model_dir:value(&a,"--model","./SmaulNative").into(),dataset:dataset.into(),output_dir:value(&a,"--output-dir",&value(&a,"--output","./SmaulNative-trained")).into(),mode:value(&a,"--mode","pretrain"),steps:value(&a,"--steps","1000").parse().unwrap(),ctx_len:value(&a,"--ctx-len","1024").parse().unwrap(),batch_size:value(&a,"--batch-size","1").parse().unwrap(),grad_accum:value(&a,"--grad-accum","1").parse().unwrap(),lr:value(&a,"--lr","1e-4").parse().unwrap(),min_lr:value(&a,"--min-lr","0").parse().unwrap(),warmup:value(&a,"--warmup","0").parse().unwrap(),save_every:value(&a,"--save-every","100").parse().unwrap(),log_every:value(&a,"--log-every","10").parse().unwrap(),resume:has(&a,"--resume"),optimizer:value(&a,"--optimizer","lion")}}
fn cosine_lr(base:f32,min:f32,step:usize,total:usize,warmup:usize)->f32{if warmup>0&&step<warmup{return base*(step+1)as f32/warmup as f32}let p=if total<=warmup{1.0}else{(step.saturating_sub(warmup)as f32/(total-warmup)as f32).min(1.0)};min+(base-min)*0.5*(1.0+(std::f32::consts::PI*p).cos())}
fn load_state(path:&Path)->State{fs::read_to_string(path).ok().and_then(|s|serde_json::from_str(&s).ok()).unwrap_or_default()}
fn save_state(path:&Path,s:&State){let _=fs::write(path,serde_json::to_string_pretty(s).unwrap());}
fn sft_step(model:&smaul_native::rwkv_model::RwkvModel,example:&smaul_native::sft_dataset::SftExample)->ModelTrainStep{let(logits,tape,state)=model.forward_with_tape_and_state(&example.input,None);let mut grad=Array2::zeros(logits.dim());let mut loss=0.0;let mut count=0usize;for r in 0..logits.nrows(){let target=example.labels[r];if target<0{continue}let row=logits.row(r);let m=row.iter().copied().fold(f32::NEG_INFINITY,f32::max);let mut sum=0.0;for&x in row{sum+=(x-m).exp()}let logz=m+sum.ln();loss+=logz-row[target as usize];for c in 0..logits.ncols(){grad[[r,c]]=(row[c]-m).exp()/sum;if c==target as usize{grad[[r,c]]-=1.0}}count+=1}let inv=1.0/count.max(1)as f32;grad.mapv_inplace(|x|x*inv);ModelTrainStep::from_logits_gradient(model,&example.input,logits,tape,state,loss*inv,grad)}
fn main()->Result<(),String>{let args=parse();if !matches!(args.mode.as_str(),"pretrain"|"sft"){return Err("--mode must be pretrain or sft".into())}if !matches!(args.optimizer.as_str(),"lion"|"adamw"){return Err("--optimizer must be lion or adamw".into())}if args.steps==0||args.ctx_len==0||args.batch_size==0||args.grad_accum==0{return Err("steps, ctx-len, batch-size and grad-accum must be > 0".into())}let model_path=if args.resume&&args.output_dir.join("config.json").exists(){args.output_dir.clone()}else{args.model_dir.clone()};let mut pretrained=PretrainedModel::load(&model_path)?;let mut data=if args.mode=="sft"{Data::Sft(SftDataset::open(&args.dataset,pretrained.tokenizer.clone(),args.ctx_len)?)}else if args.dataset.is_dir(){Data::Multi(MultiFileDatasetStream::open_discovered(&args.dataset,pretrained.tokenizer.clone(),args.ctx_len)?)}else{Data::Single(DatasetStream::open(&args.dataset,pretrained.tokenizer.clone(),args.ctx_len)?)};let state_path=args.output_dir.join("training_state.json");let mut state=if args.resume{load_state(&state_path)}else{State::default()};let kind=if args.optimizer=="adamw"{OptimizerKind::AdamW}else{OptimizerKind::Lion};let mut train=TrainStep::new_with_optimizer(&pretrained.model,args.lr,kind);let opt_path=args.output_dir.join("optimizer.bin");if args.resume&&opt_path.exists(){let bytes=fs::read(&opt_path).map_err(|e|e.to_string())?;train.load_optimizer_state_bytes(&bytes)?}
println!("[MODEL] {} parameters",pretrained.model.parameter_count());println!("[TRAIN] mode={} optimizer={} steps={} batch={} grad_accum={} lr={}",args.mode,args.optimizer,args.steps,args.batch_size,args.grad_accum,args.lr);
while state.step<args.steps{let lr=cosine_lr(args.lr,args.min_lr,state.step,args.steps,args.warmup);train.set_lr(lr);let mut accumulated:Option<ModelGradients>=None;let mut loss_sum=0.0;let mut samples=0usize;for _ in 0..args.grad_accum{for _ in 0..args.batch_size{let step=if args.mode=="sft"{loop{match &mut data{Data::Sft(sft)=>{if let Some(ex)=sft.next_example()?{break sft_step(&pretrained.model,&ex)}sft.reset()},_=>unreachable!()}}}else{let batch=match data.next()?{Some(batch)=>batch,None=>return Err("dataset ended before training reached requested steps".into())};state.tokens+=batch.input.len();let targets=Array1::from_vec(batch.target);ModelTrainStep::run(&pretrained.model,&batch.input,&targets)};loss_sum+=step.loss;samples+=1;if args.mode=="sft"{state.tokens+=args.ctx_len}if let Some(g)=&mut accumulated{g.add_in_place(&step.gradients)}else{accumulated=Some(step.gradients)}}}let gradients=accumulated.ok_or("no gradients accumulated")?;train.step(&mut pretrained.model,&gradients);state.step+=1;if state.step%args.log_every==0{println!("step {} | loss {:.5} | lr {:.3e} | tokens {}",state.step,loss_sum/samples.max(1)as f32,lr,state.tokens)}if state.step%args.save_every==0||state.step==args.steps{fs::create_dir_all(&args.output_dir).map_err(|e|e.to_string())?;pretrained.save(&args.output_dir)?;fs::write(&opt_path,train.optimizer_state_bytes()).map_err(|e|e.to_string())?;save_state(&state_path,&state);println!("[SAVE] {}",args.output_dir.display())}}Ok(())}
